    '스위치 환경에서는 ★ARP 스푸핑 · MAC Flooding(Switch Jamming) · 포트 미러링★ 을 병행해야 가능',
    '도구 — Wireshark · tcpdump · dsniff · ettercap · Cain&Abel',
