    '흐름 — ① AS 에 인증 → ② ★TGT★ 수령 → ③ TGS 에 TGT 제시 → ④ ★서비스 티켓★ 수령 → ⑤ 서버 접속',
    '특징 — ★대칭키 기반★ · 패스워드가 네트워크에 흐르지 않음 · ★SSO 구현★',
