    '★위험 메서드 — PUT·DELETE(파일 조작) · TRACE(★XST 공격★)★ → 운영 서버에서 차단',
    'GET 은 URL 에 파라미터가 남아 ★로그·리퍼러에 민감정보 노출★ → 인증 정보는 POST'
